                person_handbag_pairs.append((person, handbag))

    common_persons = set(person for person, _ in person_suitcase_pairs) & set(person for person, _ in person_handbag_pairs)

    if not common_persons:
        return image_patch

    common_person = next(iter(common_persons))
    return common_person

